@pytest.mark.parametrize("params,status_code", [
    ({"username": "testuser", "password": "testpass"}, 200),     # Successful login
    ({"username": "incorrect", "password": "wrongpass"}, 400),  # Invalid login
    ({}, 400),                                                  # Missing username/password
])
def test_user_login(base_url, auth_headers, params, status_code):
    """
    Test the /user/login endpoint.
    Covers:
    - Successful login (200)
    - Invalid username/password (400)
    - Missing username/password (400)
    """
    url = f"{base_url}/user/login"
    response = requests.get(url, params=params, headers=auth_headers)

    # Validate response status code
    assert response.status_code == status_code

    if response.status_code == 200:
        # Validate response headers
        assert "X-Rate-Limit" in response.headers
        assert "X-Expires-After" in response.headers

        # Validate headers are the correct data type
        assert isinstance(response.headers["X-Rate-Limit"], str)
        assert isinstance(response.headers["X-Expires-After"], str)

    elif response.status_code == 400:
        assert response.json() == {"error": "Invalid username/password supplied"}

    else:  # Unexpected error
        assert response.status_code >= 500, "Server error"


def test_authentication_invalid_token(base_url):
    """
    Test with invalid authorization token.
    Ensures the system properly rejects requests with wrong tokens.
    """
    url = f"{base_url}/user/login"
    headers = {"Authorization": "Bearer invalidtoken", "x-api-key": "invalidkey"}
    response = requests.get(url, headers=headers)

    assert response.status_code == 401, "Unauthorized access allowed unexpectedly."


def test_authentication_missing_token(base_url):
    """
    Test with missing authorization headers.
    Ensures the system properly rejects requests without authentication.
    """
    url = f"{base_url}/user/login"
    response = requests.get(url)

    assert response.status_code == 401, "Missing authentication headers not handled."


